args.sql:
SELECT DISTINCT a.acct_ref FROM accounts a WHERE EXISTS (
    SELECT 1 FROM security_sessions ss 
    WHERE ss.acct_gate = a.acct_ref 
    AND (ss.session_telemetry->'session_stats'->>'session_count')::int > 1000
) OR EXISTS (
    SELECT 1 FROM content_activity ca 
    WHERE ca.acct_slot = a.acct_ref 
    AND (ca.content_metrics->'posting'->>'posts_per_day')::float > 50
);

SELECT DISTINCT a.acct_ref, pr."HandleMask" FROM accounts a JOIN profiles pr ON a.acct_ref = pr.acct_anchor WHERE EXISTS (
    SELECT 1 FROM security_sessions ss 
    WHERE ss.acct_gate = a.acct_ref 
    AND (ss.session_telemetry->'session_stats'->>'session_count')::int > 1000
) OR EXISTS (
    SELECT 1 FROM content_activity ca 
    WHERE ca.acct_slot = a.acct_ref 
    AND (ca.content_metrics->'posting'->>'posts_per_day')::float > 50
);

SELECT COUNT(*) FROM (
SELECT DISTINCT a.acct_ref, pr."HandleMask" FROM accounts a JOIN profiles pr ON a.acct_ref = pr.acct_anchor WHERE EXISTS (
    SELECT 1 FROM security_sessions ss 
    WHERE ss.acct_gate = a.acct_ref 
    AND (ss.session_telemetry->'session_stats'->>'session_count')::int > 1000
) OR EXISTS (
    SELECT 1 FROM content_activity ca 
    WHERE ca.acct_slot = a.acct_ref 
    AND (ca.content_metrics->'posting'->>'posts_per_day')::float > 50
)) t;

SELECT DISTINCT a.acct_ref, pr."HandleMask" FROM accounts a JOIN profiles pr ON a.acct_ref = pr.acct_anchor WHERE EXISTS (
    SELECT 1 FROM security_sessions ss 
    WHERE ss.acct_gate = a.acct_ref 
    AND (ss.session_telemetry->'session_stats'->>'session_count')::int > 1000
) OR EXISTS (
    SELECT 1 FROM content_activity ca 
    WHERE ca.acct_slot = a.acct_ref 
    AND (ca.content_metrics->'posting'->>'posts_per_day')::float > 50
);

